    stmts: std.ArrayListUnmanaged(Stmt),
    scopes: std.ArrayListUnmanaged(*Scope),
    symbols: std.ArrayListUnmanaged(Symbol),
    import_records: std.ArrayListUnmanaged(ImportRecord),
    named_imports: js_ast.Ast.NamedImports,
    named_exports: js_ast.Ast.NamedExports,
    import_records_for_current_part: std.ArrayListUnmanaged(u32),
    export_star_import_records: std.ArrayListUnmanaged(u32),
    current_scope: *Scope,
    log: Logger.Log,
    module_ref: SymbolRef,
    declared_symbols: js_ast.DeclaredSymbol.List,
    hot_reloading: bool,
    hmr_api_ref: SymbolRef,

pub fn init(allocator: std.mem.Allocator, source: *const Logger.Source, hot_reloading: bool) !AstBuilder {
            const scope = try allocator.create(Scope);
            scope.* = .{ .kind = .entry, .label_ref = null, .parent = null, .generated = .{} };
            var ab: AstBuilder = .{ .allocator = allocator, .current_scope = scope, .source = source, .source_index = @as(u31, @truncate(source.index.get())), .stmts = .{}, .scopes = .{}, .symbols = .{}, .import_records = .{}, .import_records_for_current_part = .{}, .named_imports = .{}, .named_exports = .{}, .log = Logger.Log.init(allocator), .export_star_import_records = .{}, .declared_symbols = .{}, .hot_reloading = hot_reloading, .module_ref = undefined, .hmr_api_ref = undefined };
            _ = &ab;
            ab.module_ref = try ab.newSymbol(.other, "module");
            ab.hmr_api_ref = try ab.newSymbol(.other, "hmr");
            return ab;
    }

pub fn pushScope(self: *AstBuilder, kind: Scope.Kind) *js_ast.Scope {
            _ = try self.scopes.ensureUnusedCapacity(self.allocator, 1);
            _ = try self.current_scope.children.ensureUnusedCapacity(self.allocator, 1);
            const scope = try self.allocator.create(Scope);
            scope.* = .{ .kind = kind, .label_ref = null, .parent = self.current_scope, .generated = .{} };
            _ = self.current_scope.children.appendAssumeCapacity(scope);
            _ = self.scopes.appendAssumeCapacity(self.current_scope);
            self.current_scope = scope;
            return scope;
    }

pub fn popScope(self: *AstBuilder) void {
            self.current_scope = self.scopes.pop();
    }

pub fn newSymbol(self: *AstBuilder, kind: Symbol.Kind, identifier: []const u8) !SymbolRef {
            const inner_index: Ref.Int = @as(Ref.Int, @truncate(self.symbols.items.len));
            _ = try self.symbols.append(self.allocator, .{ .kind = kind, .original_name = identifier });
            const sym_ref: SymbolRef = .{ .inner_index = inner_index, .source_index = self.source_index, .tag = .symbol };
            _ = try self.current_scope.generated.append(self.allocator, sym_ref);
            _ = try self.declared_symbols.append(self.allocator, .{ .@"ref" = sym_ref, .is_top_level = ((self.scopes.items.len == 0) or (self.current_scope == self.scopes.items[0])) });
            return sym_ref;
    }

pub fn getSymbol(self: *AstBuilder, sym_ref: SymbolRef) *Symbol {
            _ = bun.assert((sym_ref.source_index == self.source.index.get()));
            return (&self.symbols.items[@as(usize, @intCast(sym_ref.inner_index))]);
    }

pub fn addImportRecord(self: *AstBuilder, path: []const u8, kind: ImportKind) !u32 {
            const index = self.import_records.items.len;
            _ = try self.import_records.append(self.allocator, .{ .path = bun.fs.Path.init(path), .kind = kind, .range = .{} });
            return @as(u32, @truncate(index));
    }

pub fn addImportStmt(self: *AstBuilder, path: []const u8, identifiers_to_import: anytype) !ImportStmtReturnType(identifiers_to_import) {
            var out: ImportStmtReturnType(identifiers_to_import) = undefined;
            _ = &out;
            const record = try self.addImportRecord(path, .stmt);
            var path_name = bun.fs.PathName.init(path);
            _ = &path_name;
            const name = try strings.append(self.allocator, "import_", try path_name.nonUniqueNameString(self.allocator));
            const namespace_ref = try self.newSymbol(.other, name);
            var clauses = try self.allocator.alloc(js_ast.ClauseItem, identifiers_to_import.len);
            _ = &clauses;
            {
                var i: i32 = 0;
                _ = &i;
                const __end_0 = identifiers_to_import.len;
                while (i < __end_0) : (i += 1) {
                    const import_id: []const u8 = identifiers_to_import[@as(usize, @intCast(i))];
                    const sym_ref = try self.newSymbol(.@"import", import_id);
                    if (self.hot_reloading) {
                        self.getSymbol(sym_ref).namespace_alias = .{ .namespace_ref = namespace_ref, .alias = import_id, .import_record_index = record };
                    }
                    out[cp_cast_int(usize, i)] = self.newExpr(E.ImportIdentifier{ .@"ref" = sym_ref });
                    clauses[cp_cast_int(usize, i)] = .{ .name = .{ .loc = Logger.Loc.Empty, .@"ref" = sym_ref }, .original_name = import_id, .alias = import_id };
                }
            }
            _ = try self.appendStmt(S.Import{ .namespace_ref = namespace_ref, .import_record_index = record, .items = clauses, .is_single_line = (identifiers_to_import.len < 1) });
            return out;
    }

pub fn appendStmt(self: *AstBuilder, data: anytype) !void {
            _ = try self.stmts.ensureUnusedCapacity(self.allocator, 1);
            _ = self.stmts.appendAssumeCapacity(self.newStmt(data));
    }

pub fn newStmt(self: *AstBuilder, data: anytype) Stmt {
            _ = self.allocator;
            return Stmt.alloc(@TypeOf(data), data, Logger.Loc.Empty);
    }

pub fn newExpr(self: *AstBuilder, data: anytype) Expr {
            _ = self.allocator;
            return Expr.init(@TypeOf(data), data, Logger.Loc.Empty);
    }

pub fn newExternalSymbol(self: *AstBuilder, name: []const u8) !SymbolRef {
            const sym_ref = try self.newSymbol(.other, name);
            const sym = self.getSymbol(sym_ref);
            sym.must_not_be_renamed = true;
            return sym_ref;
    }

pub fn toBundledAst(self: *AstBuilder, target: BundlerOptions.Target) !js_ast.BundledAst {
            _ = bun.assert((self.scopes.items.len == 0));
            const module_scope = self.current_scope;
            var parts = try Part.List.initCapacity(self.allocator, 2);
            _ = &parts;
            parts.len = 2;
            (parts.mut(0)).* = .{};
            (parts.mut(1)).* = .{ .stmts = self.stmts.items, .can_be_removed_if_unused = false, .symbol_uses = uses: {
            var map: Part.SymbolUseMap = .{};
            _ = &map;
            _ = try map.ensureTotalCapacity(self.allocator, self.symbols.items.len);
            {
                var i: i32 = 0;
                _ = &i;
                const __end_1 = self.symbols.items.len;
                while (i < __end_1) : (i += 1) {
                    _ = map.putAssumeCapacity(Ref{ .tag = .symbol, .source_index = self.source_index, .inner_index = @as(Ref.Int, @truncate(i)) }, .{ .count_estimate = 1 });
                }
            }
            break :uses map;
} };
            const single_val: [1]u32 = .{ 1 };
            const single_u32 = try BabyList(u32).fromSlice(self.allocator, (&single_val));
            var top_level_symbols_to_parts = js_ast.Ast.TopLevelSymbolToParts{  };
            _ = &top_level_symbols_to_parts;
            _ = try top_level_symbols_to_parts.entries.setCapacity(self.allocator, module_scope.generated.len);
            top_level_symbols_to_parts.entries.len = module_scope.generated.len;
            const slice = top_level_symbols_to_parts.entries.slice();
            var keys = slice.items(.key);
            _ = &keys;
            var values = slice.items(.value);
            _ = &values;
            const gen_slice = module_scope.generated.slice();
            {
                var i: i32 = 0;
                _ = &i;
                const __end_2 = gen_slice.len;
                while (i < __end_2) : (i += 1) {
                    keys[cp_cast_int(usize, i)] = gen_slice[@as(usize, @intCast(i))];
                    values[cp_cast_int(usize, i)] = single_u32;
                }
            }
            _ = try top_level_symbols_to_parts.reIndex(self.allocator);
            if (self.hot_reloading) {
                var hmr_transform_ctx = js_parser.ConvertESMExportsForHmr{ .last_part = ((parts.last()) orelse (unreachable)), .is_in_node_modules = self.source.path.isNodeModule() };
                _ = &hmr_transform_ctx;
                _ = try hmr_transform_ctx.stmts.ensureTotalCapacity(self.allocator, prealloc_count: {
                const count = self.stmts.items.len;
                break :prealloc_count (count + 2);
});
                _ = try js_parser.ImportScanner.scan(AstBuilder, self, self.stmts.items, false, true, (&hmr_transform_ctx));
                _ = try hmr_transform_ctx.finalize(self, parts.slice());
                const new_parts = parts.slice();
                parts.len = @as(u32, @truncate(new_parts.len));
                _ = bun.assert((new_parts.ptr == parts.ptr));
            } else {
                const result = try js_parser.ImportScanner.scan(AstBuilder, self, self.stmts.items, false, false, .{});
                parts.mut(1).stmts = result.stmts;
            }
            parts.mut(1).declared_symbols = self.declared_symbols;
            parts.mut(1).scopes = self.scopes.items;
            parts.mut(1).import_record_indices = BabyList(u32).moveFromList((&self.import_records_for_current_part));
            return .{ .parts = parts, .module_scope = module_scope.*, .symbols = js_ast.Symbol.List.moveFromList((&self.symbols)), .exports_ref = Ref.None, .wrapper_ref = Ref.None, .module_ref = self.module_ref, .import_records = ImportRecord.List.moveFromList((&self.import_records)), .export_star_import_records = empty_u32_slice[0..0], .approximate_newline_count = 1, .exports_kind = .esm, .named_imports = self.named_imports, .named_exports = self.named_exports, .top_level_symbols_to_parts = top_level_symbols_to_parts, .char_freq = .{}, .flags = .{}, .target = target, .top_level_await_keyword = Logger.Range.None };
    }

pub fn generateTempRef(self: *AstBuilder, name: ?[]const u8) SymbolRef {
            return bun.handleOom(self.newSymbol(.other, ((name) orelse ("temp"))));
    }

pub fn recordExport(self: *AstBuilder, _: Logger.Loc, alias: []const u8, sym_ref: SymbolRef) !void {
            if (self.named_exports.get(alias)) |found| {
                _ = &found;
                _ = &found;
                _ = Output.panic("In generated file, duplicate export \"{s}\"", .{ alias });
            } else {
                _ = try self.named_exports.put(self.allocator, alias, .{ .alias_loc = Logger.Loc.Empty, .@"ref" = sym_ref });
            }
    }

pub fn recordExportedBinding(self: *AstBuilder, binding: Binding) void {
            switch (binding.data) {
.b_missing => {

},
.b_identifier => |ident| {
_ = ((self.recordExport(binding.loc, self.symbols.items[@as(usize, @intCast(ident.ref.innerIndex()))].original_name, ident.ref)) catch unreachable);
},
.b_array => |arr| {
for (arr.items) |prop| {
                _ = &prop;
                _ = self.recordExportedBinding(prop.binding);
            }
},
.b_object => |obj| {
for (cp_iter_slice(obj.properties)) |prop| {
                _ = &prop;
                _ = self.recordExportedBinding((if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value));
            }
},
}
    }

pub fn ignoreUsage(self: *AstBuilder, sym_ref: SymbolRef) void {
            _ = self.allocator;
            _ = &sym_ref;
    }

pub fn panic(self: *AstBuilder, comptime fmt: []const u8, args: anytype) noreturn {
            _ = self.allocator;
            _ = Output.panic(fmt, args);
    }

pub fn @"module.exports"(self: *AstBuilder, loc: Logger.Loc) Expr {
            return self.newExpr(E.Dot{ .name = "exports", .name_loc = loc, .target = self.newExpr(E.Identifier{ .@"ref" = self.module_ref }) });
    }
    pub const options = default_options;
    pub const import_items_for_namespace = default_import_items_for_namespace;
    pub const parser_features = ParserFeatures;
};

